import java.util.Scanner;

public class Main {
    static final long MODULO = 1000000007;

    static long computePower(long base, long exp) {
        long res = 1;
        for (int i = 0; i < exp; ++i) {
            res = (res * base) % MODULO;
        }
        return res;
    }

    static long findValue(long p, long k) {
        if (k <= 1) {
            return computePower(p, p - 1 + k);
        }
        int cycle = 1;
        long val = k;
        while (val != 1) {
            val = (val * k) % p;
            cycle++;
        }
        return computePower(p, (p - 1) / cycle);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long p = scanner.nextLong();
        long k = scanner.nextLong();
        System.out.println(findValue(p, k));
        scanner.close();
    }
}
